"""The in-task coding-task grader. Generated by step1-build-tasks/coding_tasks.py; do not edit by hand.

It runs inside the task image, on whatever ``python3`` that image has (3.7 or later), with the
standard library only, in one of three stages that ``test.sh`` selects:

- ``all`` (Harbor's own verifier, in the agent's container): put the test side back, run the tests,
  write ``reward.txt``. The reward is written as 0 first, so a crash fails the task.
- ``untrusted`` (this module's staged grader (harbor_env/agentcore_env.py) runs it as the agent user): the same
  test run, on a *copy* of the repository, writing only the JUnit report and ``run.json`` to ``--out``.
  The staged grader refuses a trial whose repository changed during this stage, and a test run
  writes caches and build output, hence the copy. Nothing written here is a score.
- ``trusted`` (as the grader user, after every agent process is gone): the score, from the task's own
  files in ``--tests`` and the JUnit report in ``--in`` only. It never reads a reward, a status or an
  exit code from ``--in``, nor anything from the agent's tree, and writes ``reward.json`` last.

Without ``tests/expected.json`` (before ``coding_tasks.py calibrate``) every stage records the test
statuses and writes no passing reward: those runs exist to find the fail-to-pass tests.

This file is copied into each task; the builder never imports or runs it.
"""

from __future__ import annotations

import argparse
import contextlib
import json
import os
import re
import shlex
import shutil
import signal
import subprocess  # nosec B404 — fixed argv lists only, never a shell string from data
import sys
import tempfile
import time
from dataclasses import dataclass
from typing import Any  # json.load returns arbitrary JSON until it is narrowed below.
from xml.etree import ElementTree  # nosec B405 — see ReportCheck: bounded size, no DTD

BASE_TAG = "task-base"
NO_TESTS_REPORTED = "(no tests reported)"
#: The trusted stage parses a report that code the agent influenced wrote: a bounded size, and no DTD.
MAX_REPORT_BYTES = 20_000_000
#: Where the repository can be seen, besides the folder the untrusted stage ran the tests in.
REPOSITORY_ROOTS = ("/app", "/work/repo")
_IDENTIFIER = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_GIT_CHUNK = 200


@dataclass(frozen=True)
class GradingSpec:
    """What ``tests/spec.json`` says about running this task's tests. Plain data."""

    workdir: str
    command: str
    run_files: tuple[str, ...]
    test_globs: tuple[str, ...]
    deleted: tuple[str, ...]
    timeout_sec: float
    environment: tuple[tuple[str, str], ...]


@dataclass(frozen=True)
class CommandRun:
    """One run of the test command: where its report is and how it ended. Plain data."""

    junit_path: str
    exit_code: int
    timed_out: bool
    seconds: float


class TaskFiles:
    """Reads the task's own files under ``/tests``. Holds no state."""

    @staticmethod
    def load_spec(tests_dir: str) -> GradingSpec:
        """The grading spec that coding_tasks.py wrote."""
        with open(os.path.join(tests_dir, "spec.json"), encoding="utf-8") as handle:
            raw: dict[str, Any] = json.load(handle)
        return GradingSpec(
            workdir=str(raw.get("workdir") or "."),
            command=str(raw["command"]),
            run_files=tuple(str(item) for item in raw["run_files"]),
            test_globs=tuple(str(item) for item in raw.get("test_globs") or ()),
            deleted=tuple(str(item) for item in raw.get("deleted") or ()),
            timeout_sec=float(raw.get("timeout_sec") or 900),
            environment=tuple(sorted((str(key), str(value)) for key, value in (raw.get("env") or {}).items())),
        )

    @staticmethod
    def load_expected(tests_dir: str) -> dict[str, list[str]] | None:
        """The fail-to-pass and pass-to-pass test ids that calibrate wrote, or None before calibration."""
        path = os.path.join(tests_dir, "expected.json")
        if not os.path.exists(path):
            return None
        with open(path, encoding="utf-8") as handle:
            raw: dict[str, Any] = json.load(handle)
        return {
            "fail_to_pass": [str(item) for item in raw["fail_to_pass"]],
            "pass_to_pass": [str(item) for item in raw["pass_to_pass"]],
        }

    @staticmethod
    def write_json(path: str, data: object) -> None:
        """Write one JSON file, sorted, so two runs of the same input give the same bytes."""
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(data, handle, indent=1, sort_keys=True)


class PathGlob:
    """The test-side glob matcher (``**`` crosses folders, ``*`` and ``?`` do not). Holds no state."""

    @staticmethod
    def compile_glob(pattern: str) -> re.Pattern[str]:
        """A regular expression that matches exactly the paths the glob names."""
        parts: list[str] = []
        index = 0
        while index < len(pattern):
            token, consumed = PathGlob.translate_at(pattern, index)
            parts.append(token)
            index += consumed
        return re.compile("^" + "".join(parts) + "$")

    @staticmethod
    def translate_at(pattern: str, index: int) -> tuple[str, int]:
        """The regular-expression text for the glob token at ``index``, and how many characters it used."""
        if pattern.startswith("**/", index):
            return "(?:.*/)?", 3
        if pattern.startswith("/**", index) and index + 3 == len(pattern):
            return "(?:/.*)?", 3
        if pattern.startswith("**", index):
            return ".*", 2
        if pattern[index] == "*":
            return "[^/]*", 1
        if pattern[index] == "?":
            return "[^/]", 1
        return re.escape(pattern[index]), 1


class RepositoryGit:
    """git over one repository, with literal pathspecs and no pager. Holds no state."""

    @staticmethod
    def run(repository: str, *arguments: str) -> subprocess.CompletedProcess[bytes]:
        """Run git in ``repository`` and return the completed process (never raises on failure)."""
        environment = dict(os.environ, GIT_PAGER="cat", LC_ALL="C")
        return subprocess.run(  # nosec B607 — runs in the task image, whose own git, bash and cp are the ones to use
            ["git", "--literal-pathspecs", "-C", repository, *arguments], capture_output=True, env=environment, check=False
        )

    @staticmethod
    def paths(output: bytes) -> list[str]:
        """The NUL-separated paths of a ``-z`` git listing."""
        return [raw.decode("utf-8", "surrogateescape") for raw in output.split(b"\0") if raw]


class HiddenTests:
    """Puts the test side of a repository back to the base commit and adds the hidden tests. Holds no state."""

    @classmethod
    def restore(cls, repository: str, globs: tuple[str, ...], notes: list[str]) -> None:
        """Restore every changed test-side path from the base tag, or remove it if the agent created it."""
        patterns = [PathGlob.compile_glob(glob) for glob in globs]
        if RepositoryGit.run(repository, "rev-parse", "--verify", "-q", BASE_TAG + "^{commit}").returncode != 0:
            notes.append("base tag missing: test-side files were not restored")
            return
        changed = RepositoryGit.paths(RepositoryGit.run(repository, "diff", "--name-only", "-z", "--no-renames", BASE_TAG).stdout)
        untracked = RepositoryGit.paths(RepositoryGit.run(repository, "ls-files", "--others", "--exclude-standard", "-z").stdout)
        restore = [path for path in changed if cls.is_test_side(path, patterns) and cls.exists_at_base(repository, path)]
        remove = [path for path in changed if cls.is_test_side(path, patterns) and path not in restore]
        remove += [path for path in untracked if cls.is_test_side(path, patterns)]
        for start in range(0, len(restore), _GIT_CHUNK):
            RepositoryGit.run(repository, "checkout", BASE_TAG, "--", *restore[start : start + _GIT_CHUNK])
        for path in remove:
            cls.remove_path(os.path.join(repository, path))
        if restore or remove:
            notes.append(f"restored {len(restore)} and removed {len(remove)} test-side files the agent changed")

    @staticmethod
    def is_test_side(path: str, patterns: list[re.Pattern[str]]) -> bool:
        """True when ``path`` is on the test side."""
        return any(pattern.match(path) for pattern in patterns)

    @staticmethod
    def exists_at_base(repository: str, path: str) -> bool:
        """True when the base commit has ``path``."""
        return RepositoryGit.run(repository, "cat-file", "-e", f"{BASE_TAG}:{path}").returncode == 0

    @staticmethod
    def remove_path(full_path: str) -> None:
        """Remove a file, a link or a folder."""
        if os.path.isdir(full_path) and not os.path.islink(full_path):
            shutil.rmtree(full_path, ignore_errors=True)
        elif os.path.lexists(full_path):
            os.remove(full_path)

    @classmethod
    def install_hidden_tests(cls, tests_dir: str, repository: str, deleted: tuple[str, ...]) -> None:
        """Copy the hidden test files in, and remove the test files the change deleted."""
        source_root = os.path.join(tests_dir, "files")
        for root, _folders, names in os.walk(source_root):
            for name in names:
                cls.install_one_file(os.path.join(root, name), source_root, repository)
        for relative in deleted:
            if os.path.lexists(os.path.join(repository, relative)):
                os.remove(os.path.join(repository, relative))

    @classmethod
    def install_one_file(cls, source: str, source_root: str, repository: str) -> None:
        """Copy one hidden test file to its place in the repository, replacing whatever is there."""
        destination = os.path.join(repository, os.path.relpath(source, source_root))
        if os.path.isdir(destination) and not os.path.islink(destination):
            shutil.rmtree(destination)
        os.makedirs(os.path.dirname(destination), exist_ok=True)
        shutil.copyfile(source, destination)
        shutil.copymode(source, destination)


class RunnerCommand:
    """Runs the profile's test command with its JUnit report going to the logs folder. Holds no state."""

    @classmethod
    def run(cls, spec: GradingSpec, repository: str, logs: str) -> CommandRun:
        """Run the command from the workdir; kill its whole process group at the timeout."""
        workdir = os.path.normpath(os.path.join(repository, spec.workdir))
        junit = os.path.join(logs, "junit.xml")
        if os.path.exists(junit):
            os.remove(junit)
        files = " ".join(shlex.quote(os.path.relpath(os.path.join(repository, path), workdir)) for path in spec.run_files)
        command = spec.command.replace("{files}", files).replace("{junit}", shlex.quote(junit))
        environment = dict(os.environ)
        environment.update(dict(spec.environment))
        started = time.time()
        with open(os.path.join(logs, "test-output.log"), "wb") as output:
            output.write(f"$ cd {workdir} && {command}\n".encode())
            output.flush()
            process = subprocess.Popen(  # nosec B607 — runs in the task image, whose own git, bash and cp are the ones to use
                ["bash", "-c", command],
                cwd=workdir,
                stdout=output,
                stderr=subprocess.STDOUT,
                env=environment,
                start_new_session=True,
            )
            exit_code, timed_out = cls.wait_or_kill(process, spec.timeout_sec)
        return CommandRun(junit_path=junit, exit_code=exit_code, timed_out=timed_out, seconds=round(time.time() - started, 2))

    @staticmethod
    def wait_or_kill(process: subprocess.Popen[bytes], timeout_sec: float) -> tuple[int, bool]:
        """The exit code, and whether the run was killed at the timeout."""
        try:
            return process.wait(timeout=timeout_sec), False
        except subprocess.TimeoutExpired:
            RunnerCommand.kill_process_group(process)
            return process.wait(), True

    @staticmethod
    def kill_process_group(process: subprocess.Popen[bytes]) -> None:
        """Kill the test command and everything it started (its own session); the process alone where there are no groups."""
        if sys.platform == "win32":  # the task images are Linux; this keeps the template importable and type-checked on Windows
            process.kill()
            return
        with contextlib.suppress(OSError):
            os.killpg(process.pid, signal.SIGKILL)


@dataclass(frozen=True)
class ReportContext:
    """How a report's file paths map to test ids: the repository on disk, or the roots and test texts. Plain data."""

    repository: str
    run_files: tuple[str, ...]
    roots: tuple[str, ...] | None = None
    texts_dir: str | None = None


@dataclass(frozen=True)
class ReportWalk:
    """The state one report walk carries: how paths map, the statuses found, the run files' texts read so far."""

    context: ReportContext
    found: dict[str, str]
    texts: dict[str, str]


class JunitReport:
    """Turns a JUnit report into ``{test id: passed|failed|skipped}``. Holds no state.

    A test id is ``<file>::<suite>::...::<test name>``. Runners whose report names no file (surefire,
    gotestsum, cargo-nextest, dotnet) get their file from the class, package or the test's own name.
    """

    @classmethod
    def statuses(cls, path: str, context: ReportContext) -> dict[str, str]:
        """Every testcase's status, or none if the report is missing or not XML."""
        if not os.path.exists(path):
            return {}
        try:
            root = ElementTree.parse(path).getroot()  # nosec B314 — ReportCheck bounds the size and refuses a DTD first
        except ElementTree.ParseError:
            return {}
        walk = ReportWalk(context=context, found={}, texts={})
        cls.walk(root if root.tag == "testsuites" else [root], [], None, walk)
        return walk.found

    @classmethod
    def walk(cls, node: Any, suites: list[str], file_hint: str | None, walk: ReportWalk) -> None:
        """Visit suites and testcases, depth first."""
        for child in node:
            if child.tag == "testsuite":
                hint = cls.relative_file(child.get("file"), walk.context) or file_hint
                cls.walk(child, [*suites, child.get("name", "")], hint, walk)
            elif child.tag == "testcase":
                cls.record_case(child, suites, file_hint, walk)

    @classmethod
    def record_case(cls, case: Any, suites: list[str], file_hint: str | None, walk: ReportWalk) -> None:
        """Add one testcase; a repeated id gets ``#2``, ``#3``, and so on."""
        name = case.get("name", "")
        found = walk.found
        file = (
            cls.relative_file(case.get("file"), walk.context)
            or file_hint
            or RunFileGuess.file_for(case.get("classname") or "", name, suites, walk.context, walk.texts)
            or case.get("classname")
            or "?"
        )
        base = "::".join([file] + [suite for suite in suites if suite] + [name])
        identifier, number = base, 2
        while identifier in found:
            identifier = f"{base} #{number}"
            number += 1
        tags = {child.tag for child in case}
        found[identifier] = "failed" if tags & {"failure", "error"} else "skipped" if "skipped" in tags else "passed"

    @staticmethod
    def relative_file(attribute: str | None, context: ReportContext) -> str | None:
        """A report's file attribute as a path relative to the repository root."""
        if not attribute:
            return None
        if context.roots is None:
            path = attribute if os.path.isabs(attribute) else os.path.join(context.repository, attribute)
            return os.path.relpath(os.path.realpath(path), os.path.realpath(context.repository))
        path = os.path.normpath(attribute)
        if not os.path.isabs(path):
            return path
        for root in context.roots:
            prefix = root.rstrip("/") + "/"
            if path.startswith(prefix):
                return path[len(prefix) :]
        return os.path.relpath(path, context.roots[0])


class RunFileGuess:
    """The run file a testcase belongs to when its report names no file. Holds no state."""

    @classmethod
    def file_for(cls, classname: str, name: str, suites: list[str], context: ReportContext, texts: dict[str, str]) -> str | None:
        """In order: a run file named as the class or a suite; the class as a path; its last part as a
        file stem or folder; the run file whose text holds the test's identifier; the only run file."""
        run_files = list(context.run_files)
        if not run_files:
            return None
        named = cls.named_run_file(classname, suites, run_files)
        if named:
            return named
        by_class = cls.from_class(re.split(r"[$+]", classname)[0], run_files)
        if by_class:
            return by_class
        by_text = cls.from_text(name, run_files, context, texts)
        if by_text:
            return by_text
        return run_files[0] if len(run_files) == 1 else None

    @staticmethod
    def named_run_file(classname: str, suites: list[str], run_files: list[str]) -> str | None:
        """A run file whose path is the class name or a suite name (vitest, jest)."""
        for named in [classname, *suites]:
            candidate = named.strip()
            candidate = candidate[2:] if candidate.startswith("./") else candidate  # no str.removeprefix on 3.7
            if candidate in run_files:
                return candidate
        return None

    @staticmethod
    def from_class(class_path: str, run_files: list[str]) -> str | None:
        """The one run file that the class names as a path, a file stem or a folder."""
        if not class_path:
            return None
        as_path = class_path.replace(".", "/").replace("::", "/")
        last = re.split(r"[./:]+", class_path)[-1]
        for hits in (
            [path for path in run_files if os.path.splitext(path)[0].endswith(as_path)],
            [path for path in run_files if os.path.splitext(os.path.basename(path))[0] == last],
            [path for path in run_files if os.path.basename(os.path.dirname(path)) == last],
        ):
            if len(hits) == 1:
                return hits[0]
        return None

    @classmethod
    def from_text(cls, name: str, run_files: list[str], context: ReportContext, texts: dict[str, str]) -> str | None:
        """The one run file whose text holds the test's identifier, or its display name."""
        leaf = cls.leaf(name)
        shown = re.split(r"[([]", name, maxsplit=1)[0].strip()
        if not leaf and len(shown) <= 3:  # noqa: PLR2004 — a shorter display name matches too much text
            return None
        pattern = re.compile(rf"\b{re.escape(leaf)}\b") if leaf else re.compile(re.escape(shown))
        hits = [path for path in run_files if pattern.search(cls.text_of(path, context, texts))]
        return hits[0] if len(hits) == 1 else None

    @staticmethod
    def leaf(name: str) -> str | None:
        """The test's own identifier in a runner's name for it (``TestCart/sub``, ``tests::adds``, ``A.B(x: 1)``)."""
        name = re.split(r"[([]", name, maxsplit=1)[0].strip()
        if " " in name:
            return None
        name = name.split("/")[0]
        for separator in ("::", "."):
            name = name.split(separator)[-1]
        return name if _IDENTIFIER.fullmatch(name or "") else None

    @staticmethod
    def text_of(path: str, context: ReportContext, texts: dict[str, str]) -> str:
        """A run file's text: the task's own copy in the trusted stage, the repository's otherwise."""
        if path not in texts:
            try:
                with open(
                    os.path.join(context.texts_dir or context.repository, path), encoding="utf-8", errors="replace"
                ) as handle:
                    texts[path] = handle.read()
            except OSError:
                texts[path] = ""
        return texts[path]


class Grade:
    """The reward from test statuses. Holds no state."""

    @staticmethod
    def add_missing_run_files(statuses: dict[str, str], run_files: tuple[str, ...]) -> None:
        """A run file the report has no test for counts as one failed test."""
        for path in run_files:
            if not any(identifier.startswith(path + "::") for identifier in statuses):
                statuses[f"{path}::{NO_TESTS_REPORTED}"] = "failed"

    @staticmethod
    def worst(statuses: dict[str, str], identifier: str) -> str | None:
        """A test id the report holds more than once (``id``, ``id #2``) passes only if every copy passed."""
        copies = [
            status
            for key, status in statuses.items()
            if key == identifier or (key.startswith(identifier + " #") and key[len(identifier) + 2 :].isdigit())
        ]
        if not copies:
            return None
        return "passed" if all(status == "passed" for status in copies) else "failed"

    @classmethod
    def grade(cls, statuses: dict[str, str], expected: dict[str, list[str]]) -> tuple[int, list[str], list[str]]:
        """(reward, required, failing): 1 only if every fail-to-pass and pass-to-pass test passed."""
        required = expected["fail_to_pass"] + expected["pass_to_pass"]
        failing = [identifier for identifier in required if cls.worst(statuses, identifier) != "passed"]
        return (1 if required and not failing else 0), required, failing


class ReportCheck:
    """Whether the trusted stage will parse the untrusted stage's report at all. Holds no state."""

    @staticmethod
    def problem(path: str) -> str | None:
        """Why the report is refused, or None."""
        if not os.path.isfile(path) or os.path.islink(path):
            return "no JUnit report from the untrusted stage"
        if os.path.getsize(path) > MAX_REPORT_BYTES:
            return f"the JUnit report is over {MAX_REPORT_BYTES} bytes"
        with open(path, "rb") as handle:
            head = handle.read().upper()
        if b"<!DOCTYPE" in head or b"<!ENTITY" in head:
            return "the JUnit report declares a DTD or entities"
        return None


class GradingStages:
    """The three stages ``test.sh`` runs. Holds no state."""

    @classmethod
    def run_all(cls, tests_dir: str, repository: str, logs: str) -> int:
        """Harbor's own verifier: everything in the agent's container; reward.txt."""
        reward_path = os.path.join(logs, "reward.txt")
        with open(reward_path, "w", encoding="utf-8") as handle:
            handle.write("0\n")
        spec, expected = TaskFiles.load_spec(tests_dir), TaskFiles.load_expected(tests_dir)
        notes: list[str] = []
        HiddenTests.restore(repository, spec.test_globs, notes)
        HiddenTests.install_hidden_tests(tests_dir, repository, spec.deleted)
        run = RunnerCommand.run(spec, repository, logs)
        statuses = JunitReport.statuses(run.junit_path, ReportContext(repository=repository, run_files=spec.run_files))
        Grade.add_missing_run_files(statuses, spec.run_files)
        TaskFiles.write_json(
            os.path.join(logs, "results.json"),
            {
                "exit_code": run.exit_code,
                "timed_out": run.timed_out,
                "seconds": run.seconds,
                "notes": notes,
                "statuses": statuses,
            },
        )
        if expected is None:
            print(f"task grader: calibration run, {len(statuses)} test statuses recorded")
            return 0
        reward, required, failing = Grade.grade(statuses, expected)
        TaskFiles.write_json(
            os.path.join(logs, "grade.json"), {"reward": reward, "required": len(required), "failing": failing[:100]}
        )
        with open(reward_path, "w", encoding="utf-8") as handle:
            handle.write(f"{reward}\n")
        print(f"task grader: reward {reward} ({len(required) - len(failing)} of {len(required)} required tests passing)")
        return 0

    @classmethod
    def run_untrusted(cls, tests_dir: str, repository: str, out: str) -> int:
        """Run the tests on a copy of the repository; write the evidence and no reward."""
        os.makedirs(out, exist_ok=True)
        spec = TaskFiles.load_spec(tests_dir)
        scratch = tempfile.mkdtemp(prefix="task-grade-")
        try:
            copy = os.path.join(scratch, "repo")
            os.mkdir(copy)
            cls.copy_repository(repository, copy)
            notes = [f"ran on a copy of the repository at {copy}"]
            HiddenTests.restore(copy, spec.test_globs, notes)
            HiddenTests.install_hidden_tests(tests_dir, copy, spec.deleted)
            run = RunnerCommand.run(spec, copy, out)
            TaskFiles.write_json(
                os.path.join(out, "run.json"),
                {"exit_code": run.exit_code, "timed_out": run.timed_out, "seconds": run.seconds, "notes": notes, "root": copy},
            )
            print(f"task grader: untrusted stage, tests ran (exit {run.exit_code}); no reward is written here")
        finally:
            shutil.rmtree(scratch, ignore_errors=True)
        return 0

    @staticmethod
    def copy_repository(source: str, destination: str) -> None:
        """A copy with links kept as links: ``cp -a`` when there is one, which is much faster."""
        if (
            shutil.which("cp")
            and subprocess.run(["cp", "-a", os.path.join(source, "."), destination], check=False).returncode == 0  # nosec B607 — runs in the task image, whose own git, bash and cp are the ones to use
        ):
            return
        shutil.rmtree(destination, ignore_errors=True)
        shutil.copytree(source, destination, symlinks=True)

    @classmethod
    def run_trusted(cls, tests_dir: str, evidence: str, out: str) -> int:
        """The score from the task's files and the evidence's JUnit report; reward.json is written last."""
        os.makedirs(out, exist_ok=True)
        for name in ("reward.json", "reward.txt"):
            if os.path.lexists(os.path.join(out, name)):
                os.remove(os.path.join(out, name))
        spec, expected = TaskFiles.load_spec(tests_dir), TaskFiles.load_expected(tests_dir)
        junit = os.path.join(evidence, "junit.xml")
        problem = ReportCheck.problem(junit)
        context = ReportContext(
            repository="/", run_files=spec.run_files, roots=cls.roots(evidence), texts_dir=os.path.join(tests_dir, "files")
        )
        statuses = {} if problem else JunitReport.statuses(junit, context)
        Grade.add_missing_run_files(statuses, spec.run_files)
        TaskFiles.write_json(os.path.join(out, "results.json"), {"statuses": statuses, "notes": [problem] if problem else []})
        if expected is None:
            TaskFiles.write_json(
                os.path.join(out, "grade.json"), {"stage": "trusted", "calibration": True, "report": problem or "parsed"}
            )
            print(f"task grader: calibration run, {len(statuses)} test statuses recorded; no reward")
            return 0
        reward, required, failing = Grade.grade(statuses, expected)
        TaskFiles.write_json(
            os.path.join(out, "grade.json"),
            {
                "reward": reward,
                "required": len(required),
                "failing": failing[:100],
                "stage": "trusted",
                "report": problem or "parsed",
            },
        )
        TaskFiles.write_json(os.path.join(out, "reward.json"), {"reward": float(reward)})
        print(
            f"task grader: trusted stage, reward {reward} "
            f"({len(required) - len(failing)} of {len(required)} required tests passing)"
        )
        return 0

    @staticmethod
    def roots(evidence: str) -> tuple[str, ...]:
        """The folder the untrusted stage says it ran in (only to map paths to ids), then the repository's own roots."""
        try:
            with open(os.path.join(evidence, "run.json"), encoding="utf-8") as handle:
                ran_in = json.load(handle).get("root")
        except (OSError, ValueError, AttributeError):
            ran_in = None
        if isinstance(ran_in, str) and os.path.isabs(ran_in):
            return (os.path.normpath(ran_in), *REPOSITORY_ROOTS)
        return REPOSITORY_ROOTS

    @classmethod
    def main(cls, argv: list[str]) -> int:
        """Parse ``--stage`` and run it."""
        parser = argparse.ArgumentParser(prog="grader.py")
        parser.add_argument("--stage", choices=("all", "untrusted", "trusted"), default="all")
        parser.add_argument("--tests", required=True)
        parser.add_argument("--app")
        parser.add_argument("--logs")
        parser.add_argument("--in", dest="evidence")
        parser.add_argument("--out")
        arguments = parser.parse_args(argv)
        if arguments.stage == "all":
            return cls.run_all(arguments.tests, arguments.app, arguments.logs)
        if arguments.stage == "untrusted":
            return cls.run_untrusted(arguments.tests, arguments.app, arguments.out)
        return cls.run_trusted(arguments.tests, arguments.evidence, arguments.out)


if __name__ == "__main__":
    sys.exit(GradingStages.main(sys.argv[1:]))
